// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool, IStolenNftOracle, Factory} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    MockNFT nft;
    address seller = address(0xA11);
    uint256 tokenId = 1;

    // c reads Factory(factory).protocolFeeRate(); factory == this test contract
    uint16 public protocolFeeRate = 0;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
        nft = new MockNFT();
        nft.mint(seller, tokenId);
        vm.deal(address(c), type(uint128).max);
    }

    function testFuzz_property(uint128 vBase, uint128 vNft, uint16 feeRate) public {
        vBase = uint128(bound(vBase, 1e18, 1e20));
        vNft = uint128(bound(vNft, 1e18, 1e20));
        feeRate = uint16(bound(feeRate, 0, 5000));

        c.initialize(
            address(0),          // baseToken: ETH
            address(nft),
            vBase,
            vNft,
            0,                   // changeFee
            feeRate,
            bytes32(0),          // no merkle restriction
            false,               // useStolenNftOracle
            false                // payRoyalties
        );

        uint256 reservesBefore = c.virtualBaseTokenReserves();

        vm.prank(seller);
        (uint256 netOutputAmount, uint256 feeAmount, uint256 protocolFeeAmount) =
            c.sell(_oneId(), _oneWeight(), _emptyProof(), new IStolenNftOracle.Message[](0));

        // Rule: a sale must drain the pool's virtual base reserves by the gross
        // output (net output + trading fee + protocol fee).
        assertTrue(
            c.virtualBaseTokenReserves() == reservesBefore - (netOutputAmount + feeAmount + protocolFeeAmount),
            "virtual base reserves must decrease by gross output after sell"
        );
    }

    function _oneId() internal pure returns (uint256[] memory a) {
        a = new uint256[](1);
        a[0] = 1;
    }

    function _oneWeight() internal pure returns (uint256[] memory a) {
        a = new uint256[](1);
        a[0] = 1e18;
    }

    function _emptyProof() internal pure returns (PrivatePool.MerkleMultiProof memory p) {
        p.proof = new bytes32[](0);
        p.flags = new bool[](0);
    }
}

contract MockNFT {
    mapping(uint256 => address) public ownerOf;

    function mint(address to, uint256 id) external {
        ownerOf[id] = to;
    }

    function balanceOf(address) external pure returns (uint256) {
        return 0;
    }

    function transferFrom(address, address to, uint256 id) external {
        ownerOf[id] = to;
    }

    function safeTransferFrom(address, address to, uint256 id) external {
        ownerOf[id] = to;
    }

    function safeTransferFrom(address, address to, uint256 id, bytes calldata) external {
        ownerOf[id] = to;
    }

    function setApprovalForAll(address, bool) external {}
}
